grammar:
DELIMITERS = "<.>" ;
LIST N = N ;
LIST V = V ;
LIST A = A ;
SECTION
ADD (@hasparent) (*) (p (*)) ;
ADD (@child) (V) (c (N)) ;

DELIMITERS = "<.>" ;
LIST N = N ;
LIST V = V ;
LIST A = A ;
SECTION
SETPARENT (V) FROM (-1 N) ;
SETCHILD (A) FROM (1 N) ;

DELIMITERS = "<.>" ;
LIST N = N ;
LIST V = V ;
LIST A = A ;
SECTION
ADDRELATION (Obj) (N) TO (1 V) ;
SETRELATION (Mod) (A) TO (1 N) ;
ADDRELATIONS (Subj) (SubjOf) (V) TO (-1* N) ;
REMRELATION (Obj) (N) TO (1 V) ;
ADD (@hasobj) (*) (r:Obj (*)) ;
ADD (@hasmod) (*) (r:Mod (*)) ;

DELIMITERS = "<.>" ;
LIST N = N ;
LIST V = V ;
LIST A = A ;
SECTION
ADDRELATION (Mod) (A) TO (1 N) ;
ADD (@hasobj) (*) (r:Obj (*)) ;

DELIMITERS = "<.>" ;
LIST N = N ;
LIST V = V ;
LIST A = A ;
SECTION
REMPARENT (A) ;
SWITCHPARENT WITHCHILD (*) - (A) (V) IF (p (N)) ;

DELIMITERS = "<.>" ;
LIST N = N ;
LIST V = V ;
LIST A = A ;
SECTION
ADD (x) (V) ;
